widget.prelude:
def check_no_adjacent(n, answer):
    # the checker: any valid order passes
    if n in (2, 3):
        return answer == -1
    if not isinstance(answer, list) or len(answer) != n:
        return False
    if sorted(answer) != list(range(1, n + 1)):
        return False
    return all(abs(answer[i] - answer[i + 1]) != 1 for i in range(n - 1))

