def no_adjacent(n):
    if n in (2, 3):
        return -1
    return list(range(2, n + 1, 2)) + list(range(1, n + 1, 2))

widget.prelude:
def check_fill(n, s, k, answer):
    # the checker: any valid list passes
    if s < n or s > n * k:
        return answer == -1
    if not isinstance(answer, list) or len(answer) != n:
        return False
    return all(isinstance(x, int) and 1 <= x <= k for x in answer) and sum(answer) == s

widget.solution:
def fill_array(n, s, k):
    if s < n or s > n * k:
        return -1
    out = []
    extra = s - n
    for _ in range(n):
        add = min(k - 1, extra)
        out.append(1 + add)
        extra -= add
    return out
